const climatesEn={"humid":{"name":"Warm Humid (Summer Rain)","weather":"Hot, wet summers · Mild winters","facts":["Hot, humid summers","Afternoon storms in some areas","Mild, cool winters"],"brief":"Summers are hot, rainy and humid, with afternoon storms and typhoons, so it is hard for people to cool down. Winters are mild and cooler, with less rain.","mission":"Block the sun, carry away heat and moisture, and keep the rain out.","lesson":"In warm, humid summer-rain climates, shade comes first, and ventilation helps cool the house when outdoor conditions allow. Outside shades stop sunlight before it reaches the glass, while a ventilated roof and windows on opposite walls carry heat away, as long as the openings still keep the rain out.","parts":{"hr1":["Ventilated double roof","An air gap carries roof heat away"],"hr2":["Dark heat-storing roof","Soaks up and stores daytime heat"],"hw1":["Deep shades & veranda","Blocks sun before it hits the walls"],"hw2":["All-glass walls","Lots of sunlight and views"],"hv1":["Cross-breeze windows","Opposite windows with rain hoods"],"hv2":["Sealed picture windows","Big glass panes that never open"]}},"dry":{"name":"Hot Desert","weather":"Hot · Dry · Big day–night swings","facts":["Intense sunlight","Very little rain","Big day–night swings","Cool nights help ventilate"],"brief":"Days are hot and dry, but nights cool down fast. The house needs to slow incoming heat and make use of cool night air.","mission":"Shade and insulate by day, slow down heat, then flush out stored heat at night.","lesson":"Hot desert climates often use heavy materials whose thermal mass slows heat down, then ventilate at night to release it. Letting hot outdoor air in during the day only adds more heat indoors.","parts":{"dr1":["Light insulated roof","Reflects sunlight, blocks heat"],"dr2":["Clear skylight roof","Lets the noon sun straight in"],"dw1":["Thick thermal-mass wall","Slows daytime heat; needs night ventilation"],"dw2":["Thin metal wall","Passes outdoor heat in fast"],"dv1":["Night vents","Releases stored heat at night"],"dv2":["Big daytime windows","Lets hot wind in at noon"]}},"cold":{"name":"Cold & Snowy","weather":"Freezing · Windy · Snowy","facts":["Long heating season","Low winter sun","Big indoor–outdoor gap"],"brief":"Indoor heat easily escapes through the roof, walls and windows, and cold drafts make rooms uncomfortable.","mission":"Wrap the house in continuous insulation, seal out drafts, and catch winter sun from the right side.","lesson":"In cold, snowy climates, stopping heat loss comes first. Continuous insulation and airtight construction cut heat flow and drafts; high-performance windows let in winter sun and keep warmth in at night. Airtight homes still need planned fresh-air ventilation.","parts":{"cr1":["Thick insulated roof","Slows indoor heat escaping through the roof"],"cr2":["Roof without insulation","Indoor heat escapes through the roof"],"cw1":["Airtight insulation layer","Stops cold spots and drafts"],"cw2":["Open ventilated wall","Lets outside wind blow through"],"cv1":["Triple-glazed sunny windows","Keeps warmth in, lets sun in"],"cv2":["Big single-pane north windows","More cold glass, more heat loss"]}},"rainy":{"name":"Tropical Rainforest","weather":"Hot all year · Rain all year","facts":["Hot all year","Plenty of rain","Usually humid air","No real winter"],"brief":"It is hot and humid all year with heavy rain almost every day, so walls and roofs struggle to dry. A house must drain fast and keep air moving.","mission":"Shed heavy rain fast, keep the walls dry, and keep air moving even while it rains.","lesson":"Tropical rainforests are hot and wet all year, so drainage, moisture control and constant airflow come first. A steep roof sheds heavy rain fast, a ventilated rainscreen lets water behind the cladding drain so the wall can dry, and rain-proof vents let air in even during storms.","parts":{"rr1":["Steep drainage roof","Sheds rain fast, with deep eaves"],"rr2":["Roof without drainage design","Rainwater pools for a long time"],"rw1":["Ventilated rainscreen wall","Drains water, lets the wall dry"],"rw2":["Absorbent cladding","Water gets in and stays in"],"rv1":["Adjustable rain-proof vents","Lets air in, keeps rain out"],"rv2":["No windows, no ventilation system","Damp, stale air has nowhere to go"]}}};
const uiText={"zh":{"slot":{"roof":"屋頂","wall":"外牆","window":"開口"},"hint":"2 選 1・安裝於{slot}","tapInstall":"點選安裝：{name}","slotDone":"{slot}已安裝{name}","slotEmpty":"拖放{slot}策略卡","dropOn":"拖至{slot}","nightLabel":"☾ 夜間排熱","resA":["房子與氣候完美合作","三項策略都回應了當地最重要的環境條件，被動式設計有效降低設備負擔。"],"resB":["整體方向正確","多數策略適合當地氣候，但有一張策略卡可能增加能耗、濕氣或熱損失。"],"resC":["這棟房子需要改造","部分策略在其他氣候可能有效，放在這裡卻造成反效果。重點不是策略本身，而是使用條件。"],"mC":"室內舒適","mE":"節能潛力","mR":"氣候韌性","toPassport":"查看設計護照 <span>→</span>","keepGoing":"繼續探索 <span>→</span>","gradeA":"完全適配","gradeB":"大致適配","gradeC":"需要改造","pts":"{n} 分","noRank":"尚無紀錄，完成第一筆挑戰吧！","needName":"請先輸入名字","rankIs":"今日第 {n} 名！","rankTie":"並列第 {n} 名！","you":"你","todayCount":"今日 {n} 位挑戰者","clearAsk":"清除今日排名？","clearYes":"清除","clearNo":"取消","cleared":"已清除","play":"▶ 播放","pause":"Ⅱ 暫停","again":"↻ 重新播放","title":"氣候建築師｜被動式設計挑戰"},"en":{"slot":{"roof":"Roof","wall":"Walls","window":"Openings"},"hint":"Pick 1 of 2","tapInstall":"Tap to install: {name}","slotDone":"{slot}: {name} installed","slotEmpty":"Drop a {slot} card","dropOn":"Drop: {slot}","nightLabel":"☾ Night cooling","resA":["House and climate in perfect harmony","All three strategies answer the most important local conditions, so the house needs far less help from machines."],"resB":["On the right track","Most strategies suit this climate, but one card may add energy use, moisture or heat loss."],"resC":["This house needs a makeover","Some strategies work in other climates but backfire here. It is not about the strategy itself, but where you use it."],"mC":"Indoor Comfort","mE":"Energy Saving","mR":"Climate Resilience","toPassport":"See my design passport <span>→</span>","keepGoing":"Keep exploring <span>→</span>","gradeA":"Perfect fit","gradeB":"Good fit","gradeC":"Needs a makeover","pts":"{n} pts","noRank":"No scores yet. Be the first!","needName":"Please enter your name","rankIs":"You're #{n} today!","rankTie":"Tied #{n}!","you":"YOU","todayCount":"{n} players today","clearAsk":"Clear today's scores?","clearYes":"Clear","clearNo":"Cancel","cleared":"Cleared","play":"▶ Play","pause":"Ⅱ Pause","again":"↻ Play again","title":"Climate Architect | Passive Design Challenge"}},htmlText={"logo":{"zh":"氣候建築師","en":"Climate Architect"},"home":{"zh":"回到首頁","en":"Home"},"h1":{"zh":"先讀懂天氣，<br><em>再蓋出好房子。</em>","en":"Read the weather,<br><em>then build a better home.</em>"},"lead":{"zh":"面對熱、濕、乾、冷等氣候，建築需要不同的外殼與通風策略。觀察環境線索，替房子裝上最適合的被動式設計！","en":"Hot, humid, dry or cold: every climate needs a different building shell and airflow plan. Read the climate clues and give the house the passive design that fits best!"},"startBtn":{"zh":"觀看 1 分 45 秒導覽 <span>認識被動式建築 →</span>","en":"Watch the 1:45 intro <span>→</span>"},"skip":{"zh":"直接開始挑戰","en":"Start the challenge"},"guideBtn":{"zh":"怎麼玩？","en":"How to play"},"metricTitle":{"zh":"模擬會用 3 個指標替你的房子評分","en":"The simulation scores your house on 3 measures"},"mComfort":{"zh":"🌡️ 室內舒適","en":"🌡️ Indoor Comfort"},"mComfortD":{"zh":"室內的溫度、濕度和通風，能不能讓人住得舒服。","en":"Do indoor temperature, humidity and airflow make the home pleasant to live in?"},"mEnergy":{"zh":"⚡ 節能潛力","en":"⚡ Energy Saving"},"mEnergyD":{"zh":"靠房子本身的設計，能少開多少冷氣、暖氣，省下多少電。","en":"How much cooling, heating and electricity the design itself can save."},"mRes":{"zh":"🛡️ 氣候韌性","en":"🛡️ Climate Resilience"},"mResD":{"zh":"遇到熱浪、暴雨、寒流或停電時，房子還能不能保持安全耐用。","en":"Does the house stay safe and sturdy in heat waves, storms, cold snaps or power cuts?"},"c1":{"zh":"善用陽光與自然風","en":"Use sun and natural wind"},"c2":{"zh":"降低冷暖房需求","en":"Less heating and cooling"},"c3":{"zh":"因地制宜","en":"Fit the place"},"vBack":{"zh":"← 回上一頁","en":"← Back"},"vH2":{"zh":"什麼是被動式建築？","en":"What is passive design?"},"vReplay":{"zh":"↻ 重播","en":"↻ Replay"},"vVoice":{"zh":"旁白聲音","en":"Narrator"},"vSkip":{"zh":"開始氣候挑戰 <span>→</span>","en":"Start the challenge <span>→</span>"},"vNote":{"zh":"動畫全長 1 分 45 秒，附中文旁白與背景音樂（右上角 ♪ 可關閉聲音）；現場較吵時也可直接閱讀字幕。","en":"The animation runs 1 min 45 s with narration and background music (tap ♪ at the top right to mute). If it is noisy, just read the captions."},"mapH2":{"zh":"選擇氣候區","en":"Choose a climate"},"mapP":{"zh":"每個地方的太陽、風、溫度與濕度都不同。完成全部 4 關，成為真正的氣候建築師。","en":"Every place has its own sun, wind, temperature and humidity. Finish all 4 levels to become a true Climate Architect."},"mapProg":{"zh":"總進度","en":"Progress"},"backMap":{"zh":"← 氣候地圖","en":"← Climate map"},"clues":{"zh":"環境線索","en":"Climate clues"},"mission":{"zh":"本關任務","en":"Your mission"},"section":{"zh":"房屋剖面｜將策略卡拖到房子上","en":"House section | Drag cards onto the house"},"installed":{"zh":"已安裝","en":"Installed"},"partsLib":{"zh":"被動式策略設計","en":"Passive design strategies"},"partsH3":{"zh":"拖曳 3 張策略卡到房子","en":"Drag 3 cards onto the house"},"partsP":{"zh":"拖放後外型會立即改變；觸控設備也可直接點選。","en":"The house changes as soon as you drop a card. On touch screens you can also just tap."},"testBtn":{"zh":"啟動氣候模擬 <span>→</span>","en":"Run the climate simulation <span>→</span>"},"fBack":{"zh":"← 回上一頁","en":"← Back"},"simRes":{"zh":"模擬結果","en":"Simulation results"},"fitScore":{"zh":"氣候適應力","en":"Climate fit"},"note":{"zh":"建築科學筆記","en":"Building science note"},"finalH2":{"zh":"氣候建築師認證完成","en":"Certified Climate Architect!"},"finalP":{"zh":"你已完成四種氣候區的房屋設計。真正的好建築，會先回應所在地的氣候，再用設備補足需求。","en":"You designed houses for all four climate zones. Great buildings respond to their local climate first, then use machines only to fill the gaps."},"total":{"zh":"總分","en":"Total"},"restart":{"zh":"換下一位挑戰 <span>↻</span>","en":"Next player <span>↻</span>"},"passport":{"zh":"氣候設計護照","en":"Climate design passport"},"takeaway":{"zh":"帶走一個觀念","en":"One idea to take home"},"takeawayP":{"zh":"被動式設計不是固定配方。相同策略在不同氣候中，可能帶來不同甚至相反的效果。","en":"Passive design is not a fixed recipe. The same strategy can have different, even opposite, effects in different climates."},"rankH3":{"zh":"今日挑戰排行榜","en":"Today's top scores"},"pName":{"zh":"玩家名字","en":"Player name"},"saveRank":{"zh":"登記成績","en":"Save score"},"privacy":{"zh":"排名每天自動重置，只存在這台裝置，不會上傳個人資料。","en":"Scores reset every day and stay on this device. Nothing is uploaded."},"gH2":{"zh":"觀察、安裝、模擬","en":"Observe, install, simulate"},"g1":{"zh":"讀懂氣候線索","en":"Read the climate clues"},"g1d":{"zh":"查看溫度、日照、雨量與風的特性。","en":"Check the temperature, sunlight, rainfall and wind."},"g2":{"zh":"安裝 3 張策略卡","en":"Install 3 strategy cards"},"g2d":{"zh":"屋頂、外牆及開口各選一項被動式策略。","en":"Pick one passive strategy each for the roof, walls and openings."},"g3":{"zh":"啟動模擬","en":"Run the simulation"},"g3d":{"zh":"檢查舒適、節能與韌性，了解策略背後的原理。","en":"See your comfort, energy and resilience scores and learn the science behind them."},"gStart":{"zh":"開始挑戰 <span>→</span>","en":"Start <span>→</span>"}},htmlAttrText={"phName":{"zh":"輸入名字","en":"Your name"}};
const $=s=>document.querySelector(s),screens=['lang','start','video','map','game','feedback','final'];let lang='zh',climates=climatesZh,slotNames=uiText.zh.slot,state={current:0,selected:{},scores:{}},soundOn=true;
function tr(key,vars={}){return String(uiText[lang][key]).replace(/\{(\w+)\}/g,(_,k)=>vars[k])}
function localClimates(){return lang==='zh'?climatesZh:climatesZh.map(c=>{const t=climatesEn[c.id];return {...c,...t,parts:c.parts.map(p=>({...p,name:t.parts[p.id][0],desc:t.parts[p.id][1]}))}})}
function show(id){if(id!=='video'){pauseVideo();stopNarration()}screens.forEach(x=>$('#'+x).classList.toggle('active',x===id));$('#homeBtn').classList.toggle('hidden',id==='lang'||id==='start'||id==='video');$('#langBtn').classList.toggle('hidden',id!=='start');scrollTo({top:0,behavior:'smooth'})}
function tone(f=500,d=.08){if(!soundOn)return;try{const c=new(AudioContext||webkitAudioContext),o=c.createOscillator(),g=c.createGain();o.frequency.value=f;o.type='triangle';g.gain.setValueAtTime(.04,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+d);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+d)}catch(e){}}
function reset(toLang){state={current:0,selected:{},scores:{}};renderMap();show(toLang?'lang':'start')}
function setLang(l){lang=l;climates=localClimates();explainerScenes=l==='zh'?scenesZh:scenesEn;slotNames=uiText[l].slot;document.documentElement.lang=l==='zh'?'zh-Hant':'en';document.title=tr('title');document.querySelectorAll('[data-i18n]').forEach(el=>el.innerHTML=htmlText[el.dataset.i18n][l]);document.querySelectorAll('[data-i18n-ph]').forEach(el=>el.placeholder=htmlAttrText[el.dataset.i18nPh][l]);videoScene=-1;narrDone=-1;renderVideo();pauseVideo();renderVoiceMenu();renderMap()}
function chooseLang(l){setLang(l);show('start')}
function renderMap(){const done=Object.keys(state.scores).length;$('#mapCount').textContent=`${done}／4`;$('#mapProgress').style.width=done/4*100+'%';$('#levelGrid').innerHTML=climates.map((c,i)=>{const complete=state.scores[c.id]!=null,unlocked=i<=done;return `<button class="level-card ${complete?'done':''} ${unlocked?'':'locked'}" data-level="${i}" ${unlocked?'':'disabled'} style="--accent:${c.accent}"><div class="level-art">${c.icon}</div><div class="level-info"><small>LEVEL 0${i+1}・${c.en}</small><h3>${c.name}</h3><p>${c.weather}</p></div></button>`}).join('');document.querySelectorAll('.level-card:not(.locked)').forEach(b=>b.onclick=()=>openLevel(+b.dataset.level))}
function openLevel(i){state.current=i;state.selected={};state.flip=pickFlip();const c=climates[i];document.documentElement.style.setProperty('--accent',c.accent);$('#levelNo').textContent=`LEVEL 0${i+1}・${c.en}`;$('#climateName').textContent=c.icon+' '+c.name;$('#climateFacts').innerHTML=c.facts.map(x=>`<span>${x}</span>`).join('');$('#sceneIcon').textContent=c.icon;$('#sceneTemp').textContent=c.temp;$('#sceneWeather').textContent=c.weather;$('#climateBrief').textContent=c.brief;$('#missionText').textContent=c.mission;renderParts();updateBuild();show('game')}
function renderParts(){const c=climates[state.current],groupInfo={roof:{icon:'⌂',hint:tr('hint',{slot:slotNames.roof})},wall:{icon:'▥',hint:tr('hint',{slot:slotNames.wall})},window:{icon:'▣',hint:tr('hint',{slot:slotNames.window})}};$('#partsGrid').innerHTML=['roof','wall','window'].map(slot=>`<section class="part-group" data-type="${slot}"><div class="part-group-head"><span>${groupInfo[slot].icon}</span><div><b>${slotNames[slot]}</b><small>${groupInfo[slot].hint}</small></div></div><div class="part-choices">${partOrder(c,slot).map(p=>`<button class="part-card" data-id="${p.id}" data-slot="${p.slot}" aria-label="${tr('tapInstall',{name:p.name})}"><span class="part-tag">${slotNames[p.slot]}</span><span class="part-icon">${p.icon}</span><b>${p.name}</b><small>${p.desc}</small></button>`).join('')}</div></section>`).join('');document.querySelectorAll('.part-card').forEach(b=>{b.onclick=e=>{if(b.dataset.justDragged){e.preventDefault();return}install(b.dataset.id)};b.onpointerdown=beginPartDrag})}
function beginPartDrag(e){if(e.pointerType==='mouse'&&e.button!==0)return;const card=e.currentTarget,sx=e.clientX,sy=e.clientY,stage=$('#houseStage');let moved=false,ghost;card.setPointerCapture?.(e.pointerId);const move=ev=>{const distance=Math.hypot(ev.clientX-sx,ev.clientY-sy);if(!moved&&distance>8){moved=true;card.classList.add('dragging');ghost=card.cloneNode(true);ghost.className='part-card drag-ghost';document.body.appendChild(ghost)}if(!moved)return;ev.preventDefault();ghost.style.left=ev.clientX+'px';ghost.style.top=ev.clientY+'px';const under=document.elementFromPoint(ev.clientX,ev.clientY);stage.classList.toggle('drag-over',!!under?.closest('#houseStage'))};const end=ev=>{card.releasePointerCapture?.(e.pointerId);card.removeEventListener('pointermove',move);card.removeEventListener('pointerup',end);card.removeEventListener('pointercancel',end);if(!moved)return;const under=document.elementFromPoint(ev.clientX,ev.clientY),valid=under?.closest('#houseStage');card.dataset.justDragged='1';setTimeout(()=>delete card.dataset.justDragged,0);card.classList.remove('dragging');stage.classList.remove('drag-over');ghost?.remove();if(valid)install(card.dataset.id)};card.addEventListener('pointermove',move);card.addEventListener('pointerup',end);card.addEventListener('pointercancel',end)}
function install(id){const c=climates[state.current],p=c.parts.find(x=>x.id===id);state.selected[p.slot]=id;updateBuild();tone(480+Object.keys(state.selected).length*80)}
function metrics(){const c=climates[state.current],m={c:50,e:50,r:50};Object.values(state.selected).forEach(id=>{const p=c.parts.find(x=>x.id===id);m.c+=p.m.c;m.e+=p.m.e;m.r+=p.m.r});Object.keys(m).forEach(k=>m[k]=Math.max(0,Math.min(100,m[k])));return m}
function updateBuild(){const c=climates[state.current],chosen=Object.values(state.selected).map(id=>c.parts.find(x=>x.id===id));document.querySelectorAll('.part-card').forEach(b=>b.classList.toggle('selected',Object.values(state.selected).includes(b.dataset.id)));$('#houseModel').className='house-model '+chosen.map(p=>'part-'+p.id).join(' ');['roof','wall','window'].forEach(slot=>{const el=$('#'+slot+'Slot'),id=state.selected[slot],p=c.parts.find(x=>x.id===id);el.classList.toggle('filled',!!p);el.setAttribute('aria-label',p?tr('slotDone',{slot:slotNames[slot],name:p.name}):tr('slotEmpty',{slot:slotNames[slot]}));el.innerHTML=p?'<span class="slot-check">✓</span>':`<span>${tr('dropOn',{slot:slotNames[slot]})}</span>`});$('#installedChips').innerHTML=chosen.map(p=>`<i>${p.icon} ${p.name}</i>`).join('');$('#slotCount').textContent=`${chosen.length}／3`;const featureLabel=$('#windowFeatureLabel'),showNightLabel=state.selected.window==='dv1';featureLabel.textContent=showNightLabel?tr('nightLabel'):'';featureLabel.classList.toggle('hidden',!showNightLabel);$('#testBtn').disabled=chosen.length<3;if(window.houseView)houseView.update(c.id,chosen.map(p=>p.id));updateGuide()}
function simulate(){const c=climates[state.current],m=metrics(),score=Math.round((m.c+m.e+m.r)/3),correct=Object.values(state.selected).filter(id=>c.parts.find(x=>x.id===id).good).length;let grade,title,lead;grade=correct===3?'A':correct===2?'B':'C';[title,lead]=uiText[lang]['res'+grade];state.scores[c.id]={score,grade,selected:{...state.selected}};$('#resultScore').textContent=score;$('#resultStamp').textContent=grade;$('#resultTitle').textContent=title;$('#resultLead').textContent=lead;$('#resultBreakdown').innerHTML=`<div><b>${m.c}</b><span>${tr('mC')}</span></div><div><b>${m.e}</b><span>${tr('mE')}</span></div><div><b>${m.r}</b><span>${tr('mR')}</span></div>`;$('#lessonText').textContent=c.lesson;$('#continueBtn').innerHTML=Object.keys(state.scores).length===4?tr('toPassport'):tr('keepGoing');showRealHouse();showOops();renderReport(m,score,grade);show('feedback');tone(grade==='A'?760:grade==='B'?610:310,.18)}
function continueGame(){if(Object.keys(state.scores).length===4)showFinal();else{renderMap();show('map')}}
function showFinal(){const total=climates.reduce((s,c)=>s+(state.scores[c.id]?.score||0),0);state.totalScore=total;$('#finalScore').textContent=total;$('#passportGrid').innerHTML=climates.map(c=>{const x=state.scores[c.id];return `<div class="passport-entry"><span>${c.icon}</span><div><b>${c.name}</b><small>${tr('grade'+x.grade)}</small></div><b>${x.score}</b></div>`}).join('');$('#playerName').value='';$('#playerName').disabled=false;$('#saveRankBtn').disabled=false;$('#rankResult').textContent='';renderLeaderboard();show('final');setTimeout(()=>$('#playerName').focus(),450);tone(820,.28)}
function dayKey(t){const d=new Date(t);return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate()}
function readRanks(){try{const data=JSON.parse(localStorage.getItem('climateHouseRankings')||'[]');if(!Array.isArray(data))return [];const today=dayKey(Date.now()),list=data.filter(r=>r&&dayKey(r.time)===today);if(list.length!==data.length){try{localStorage.setItem('climateHouseRankings',JSON.stringify(list))}catch(e){}}return list}catch(e){return []}}
function sortRanks(a){return a.sort((x,y)=>y.score-x.score||x.time-y.time)}
function tieRank(list,score){return 1+list.filter(r=>r.score>score).length}
function clearRanks(){try{localStorage.removeItem('climateHouseRankings')}catch(e){}lastRankId=null;$('#rankResult').textContent='';renderLeaderboard()}
let lastRankId=null;
function safeText(value){return String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function renderLeaderboard(currentId){const all=sortRanks(readRanks()),cur=all.find(r=>r.id===currentId);let order=all;if(cur){order=all.filter(r=>r!==cur);const at=order.findIndex(r=>r.score<=cur.score);order.splice(at<0?order.length:at,0,cur)}const MAX=8;let rows=order.slice(0,MAX),pinned=null;if(cur&&order.indexOf(cur)>=MAX){rows=order.slice(0,MAX-2);pinned=cur}const row=r=>{const n=tieRank(all,r.score),klass=(n<=3?'top ':'')+(r===cur?'current':'');return `<li class="rank-row ${klass}" data-rank="${n}"><b>${safeText(r.name)}${r===cur?` <em>${tr('you')}</em>`:''}</b><span>${tr('pts',{n:r.score})}</span></li>`};$('#leaderboard').innerHTML=all.length?rows.map(row).join('')+(pinned?`<li class="rank-gap">⋯</li>`+row(pinned):''):`<li class="empty-rank">${tr('noRank')}</li>`;const c=$('#rankCount');if(c)c.textContent=all.length?tr('todayCount',{n:all.length}):''}
function saveRanking(){const input=$('#playerName'),name=input.value.trim();if(!name){$('#rankResult').textContent=tr('needName');input.focus();return}const ranks=readRanks(),entry={id:Date.now()+'-'+Math.random().toString(36).slice(2),name:name.slice(0,12),score:state.totalScore,time:Date.now()};ranks.push(entry);sortRanks(ranks);try{localStorage.setItem('climateHouseRankings',JSON.stringify(ranks.slice(0,500)))}catch(e){}const rank=tieRank(ranks,entry.score),same=ranks.filter(r=>r.score===entry.score).length;lastRankId=entry.id;$('#rankResult').textContent=same>1?tr('rankTie',{n:rank,k:same}):tr('rankIs',{n:rank});input.disabled=true;$('#saveRankBtn').disabled=true;renderLeaderboard(entry.id);tone(880,.22)}
