function playChord(){const c=audioCtx,now=c.currentTime,chord=bgmChords[bgmStep++%bgmChords.length];chord.forEach((f,k)=>{const o=c.createOscillator(),g=c.createGain();o.type=k?'sine':'triangle';o.frequency.value=k?f:f/2;g.gain.setValueAtTime(0,now);g.gain.linearRampToValueAtTime(.22,now+1.2);g.gain.setValueAtTime(.22,now+3.2);g.gain.linearRampToValueAtTime(0,now+4.8);o.connect(g);g.connect(bgmGain);o.start(now);o.stop(now+5)});const o=c.createOscillator(),g=c.createGain(),n=chord[Math.floor(Math.random()*chord.length)]*2;o.type='sine';o.frequency.value=n;g.gain.setValueAtTime(.12,now+.6);g.gain.exponentialRampToValueAtTime(.001,now+2.4);o.connect(g);g.connect(bgmGain);o.start(now+.6);o.stop(now+2.5)}
