function sceneChime(){if(!soundOn)return;try{const c=getAudio(),now=c.currentTime;[659.25,987.77].forEach((f,k)=>{const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,now+k*.12);g.gain.linearRampToValueAtTime(.05,now+k*.12+.02);g.gain.exponentialRampToValueAtTime(.001,now+k*.12+.9);o.connect(g);g.connect(c.destination);o.start(now+k*.12);o.stop(now+k*.12+1)})}catch(e){}}
function formatVideoTime(sec){const s=Math.max(0,Math.min(105,Math.floor(sec)));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function renderVideo(){const index=Math.min(explainerScenes.length-1,explainerScenes.findIndex(s=>videoElapsed>=s.from&&videoElapsed<s.to));const scene=explainerScenes[index<0?explainerScenes.length-1:index];if(videoScene!==index){videoScene=index;$('#videoStage').dataset.scene=index;$('#videoChapter').textContent=scene.chapter;$('#videoTitle').textContent=scene.title;$('#videoCaption').textContent=scene.caption;$('#videoVisual').innerHTML=scene.visual}$('#videoProgress').style.width=Math.min(100,videoElapsed/105*100)+'%';$('#videoTime').textContent=formatVideoTime(videoElapsed)+'／01:45'}
function pauseVideo(){if(videoTimer){clearInterval(videoTimer);videoTimer=null}holdNarration();stopBgm();const btn=$('#videoPlayBtn');if(btn)btn.textContent=videoElapsed>=105?tr('again'):tr('play')}
function playVideo(){if(videoElapsed>=105){videoElapsed=0;videoScene=-1;narrDone=-1;renderVideo()}videoLast=performance.now();if(videoTimer)clearInterval(videoTimer);$('#videoPlayBtn').textContent=tr('pause');videoTimer=setInterval(()=>{const now=performance.now(),prev=videoScene;const dtv=(now-videoLast)/1000;videoLast=now;videoElapsed+=dtv;if(narrHold()){narrWait+=dtv;videoElapsed=explainerScenes[videoScene].to-.05}else if(videoElapsed<explainerScenes[Math.max(0,videoScene)].to-.05)narrWait=0;if(videoElapsed>=105){videoElapsed=105;renderVideo();pauseVideo();return}renderVideo();if(videoScene!==prev){narrWait=0;sceneChime();narrate(videoScene)}},100);startBgm();resumeNarration()}
function openExplainer(){stopNarration();videoElapsed=0;videoScene=-1;narrDone=-1;show('video');renderVideo();playVideo()}
function startChallenge(){pauseVideo();renderMap();show('map')}
document.querySelectorAll('.part-slot,#houseStage').forEach(el=>{el.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move'};el.ondrop=e=>{e.preventDefault();e.stopPropagation();$('#houseStage').classList.remove('drag-over');const id=e.dataTransfer.getData('text/plain');if(id)install(id)}});
$('#startBtn').onclick=openExplainer;$('#skipIntroBtn').onclick=startChallenge;$('#videoPlayBtn').onclick=()=>videoTimer?pauseVideo():playVideo();$('#videoRestartBtn').onclick=()=>{stopNarration();videoElapsed=0;videoScene=-1;narrDone=-1;renderVideo();playVideo()};$('#videoSkipBtn').onclick=startChallenge;$('#videoBackBtn').onclick=()=>show('start');$('#guideStart').onclick=()=>{$('#guide').close();startChallenge()};$('#guideBtn').onclick=()=>$('#guide').showModal();$('#closeGuide').onclick=()=>$('#guide').close();$('#backMap').onclick=()=>{renderMap();show('map')};$('#testBtn').onclick=simulate;$('#feedbackBackBtn').onclick=()=>show('game');$('#continueBtn').onclick=continueGame;$('#saveRankBtn').onclick=saveRanking;$('#playerName').onkeydown=e=>{if(e.key==='Enter')saveRanking()};$('#restartBtn').onclick=()=>reset(true);$('#homeBtn').onclick=()=>reset();$('#soundBtn').onclick=()=>{soundOn=!soundOn;$('#soundBtn').textContent=soundOn?'♪':'×';tone();if(!soundOn){holdNarration();stopBgm()}else if(videoTimer){startBgm();resumeNarration()}};renderMap();
function fitScreen(){const fit=innerWidth>=900&&innerHeight>=500,root=document.documentElement.style;document.body.classList.toggle('fit',fit);if(!fit){['--fit','--cw','--vh'].forEach(k=>root.removeProperty(k));return}const k=Math.min(innerWidth/1280,innerHeight/720);root.setProperty('--fit',k);root.setProperty('--cw',innerWidth/k+'px');root.setProperty('--vh',innerHeight/k+'px')}
addEventListener('resize',fitScreen);fitScreen();
if($('#voiceSelect')){renderVoiceMenu();$('#voiceSelect').onchange=setVoicePref}
