function showRealHouse(){const c=climates[state.current],r=realHouses[c.id][lang],picked=Object.values(state.selected).map(id=>c.parts.find(x=>x.id===id)),hit=picked.find(p=>p.good),goal=c.parts.find(p=>p.good);
  $('#rhLabel').textContent=tr('rhLabel');$('#rhImg').src='img/real-'+c.id+'.svg';$('#rhImg').alt=r[0];$('#rhName').textContent=r[0];$('#rhPlace').textContent=r[1];$('#rhDesc').textContent=r[2];
  $('#rhLink').textContent=hit?tr('rhGood',{part:hit.name}):tr('rhTry',{part:goal.name});$('#rhCredit').textContent=tr('rhCredit')}
const oopsText={"hr2": ["屋頂變成一塊大電烤盤，到了半夜天花板還在熱情放送暖氣，全家只能抱著電風扇睡。", "The roof turns into a giant hot plate, and the ceiling keeps radiating heat past midnight. Everyone sleeps hugging a fan."], "hw2": ["房子秒變溫室，盆栽長得很開心，人卻熱到想搬進冰箱住。", "The house becomes a greenhouse: the plants love it, the people want to move into the fridge."], "hv2": ["窗戶打不開，濕氣只好留下來長住，衣服晾三天還是潮潮的，牆角還冒出黴菌小家族。", "The windows never open, so humidity moves in for good. Laundry stays damp for days and mold starts a little family in the corner."], "dr2": ["正午陽光直接灑進客廳，坐在沙發上就像在做日光浴，冷氣開到最強也追不上。", "Noon sun pours straight into the living room. The sofa feels like a sunbed, and the AC on full blast still can’t keep up."], "dw2": ["薄薄的金屬牆把外面的熱直接送進來，屋裡像曬太陽的鐵便當盒，摸到牆會大喊「燙！」", "Thin metal walls pass the heat straight in. The house feels like a lunch tin in the sun, and touching the wall goes: ouch!"], "dv2": ["中午打開大窗，吹進來的是沙漠熱風，就像有人拿吹風機對著你的臉吹。", "Opening big windows at noon lets in desert wind that feels like a hair dryer pointed at your face."], "cr2": ["好不容易暖起來的熱氣從屋頂一路溜走，暖氣費一直往上衝，大家在屋裡還得戴毛帽。", "Hard-won heat slips out through the roof. The heating bill soars and everyone wears woolly hats indoors."], "cw2": ["寒風自由穿過客廳，房子變成冷風隧道，熱湯端上桌三秒就涼了。", "Icy wind blows freely through the living room. The house becomes a wind tunnel, and hot soup goes cold in three seconds."], "cv2": ["大片單層玻璃整天對著寒冷的北方，窗邊冷得像冰箱門，玻璃上還結了一層霜。", "A big single pane faces the cold north all day. The window seat feels like a fridge door, and frost grows on the glass."], "rr2": ["雨水在屋頂聚成小池塘，青蛙開心地搬來住，天花板卻開始滴答滴答漏水。", "Rain pools into a little pond on the roof. The frogs move in happily, but the ceiling starts to drip, drip, drip."], "rw2": ["外牆像海綿一樣吸飽雨水、怎麼也乾不了，長出青苔和黴斑，像穿著一件永遠不乾的濕外套。", "The walls soak up rain like a sponge and never dry, sprouting moss and mold, like a wet coat that never dries."], "rv2": ["沒有窗也沒有換氣設備，屋裡又悶又潮，霉味賴著不走，連浴室鏡子都整天霧濛濛。", "No windows and no ventilation, so the house gets stuffy and damp. The musty smell won’t leave, and even the mirror stays fogged up."]};
