function showOops(){const c=climates[state.current],wrong=Object.values(state.selected).filter(id=>!c.parts.find(x=>x.id===id).good&&oopsText[id]);
  $('#oops').classList.toggle('hidden',!wrong.length);$('#feedback').classList.toggle('has-oops',!!wrong.length);$('#oopsTitle').textContent=tr('oopsTitle',{name:c.name});
  $('#oopsList').innerHTML=wrong.map(id=>`<li><b>${c.parts.find(x=>x.id===id).name}</b>${oopsText[id][lang==='zh'?0:1]}</li>`).join('')}
function metrics(){const c=climates[state.current],raw={c:50,e:50,r:50},best={c:50,e:50,r:50};
  Object.values(state.selected).forEach(id=>{const p=c.parts.find(x=>x.id===id);for(const k in raw)raw[k]+=p.m[k]});
  c.parts.filter(p=>p.good).forEach(p=>{for(const k in best)best[k]+=p.m[k]});
  const m={};for(const k in raw)m[k]=Math.max(0,Math.min(100,Math.round(raw[k]*100/best[k])));return m}
Object.assign(uiText.zh,{rpPrefix:'氣候建築檢測報告：',rpRemark:'檢查員備註：',rpSign:'氣候建築師檢測中心',rpDisclaimer:'本遊戲分數為依據氣候適應原則設計的教育性評估，並非實際建築能耗模擬或節能效益預測。',rpPicks:'檢查項目',sealA:'優良通過',sealB:'部分合格',sealC:'需要改造'});
