function renderReport(m,score,grade){const c=climates[state.current],tone=v=>v>=80?'ok':v>=60?'mid':'low';
  $('#feedback').dataset.grade=grade;$('#rpClimate').textContent=c.name;$('#rpPrefix').textContent=tr('rpPrefix');$('#rpSealText').textContent=tr('seal'+grade);
  $('#rpRemark').textContent=tr('rpRemark');$('#rpSign').textContent=tr('rpSign');$('#rpDisclaimer').textContent=tr('rpDisclaimer');
  $('#rpPicks').innerHTML=`<tr class="rp-picks"><td>${tr('rpPicks')}</td><td colspan="2">${['roof','wall','window'].map(s=>{const p=c.parts.find(x=>x.id===state.selected[s]);return p?`<span class="${p.good?'ok':'bad'}"><small>${slotNames[s]}</small>${p.name}<i>${p.good?'✓':'✗'}</i></span>`:''}).join('')}</td></tr>`;
  $('#resultBreakdown').innerHTML=[['mC',m.c],['mE',m.e],['mR',m.r]].map(([k,v])=>`<tr><td>${tr(k)}</td><td><div class="meter ${tone(v)}"><b style="width:${Math.max(4,Math.min(100,v))}%"></b></div></td><td>${v}</td></tr>`).join('');
  $('#resultScore').className=tone(score)}

